namespace sv_c2658095691f4e19b148408a3d210ef9.Components;

public enum ScreenSize
{
    Mobile,
    Tablet,
    Desktop
}

@implements IAsyncDisposable
@inject IJSRuntime JS

<CascadingValue Value="currentSize">
    @ChildContent
</CascadingValue>

@code {
    [Parameter]
    public RenderFragment? ChildContent { get; set; }

    private ScreenSize currentSize = ScreenSize.Desktop;
    private IJSObjectReference? module;
    private DotNetObjectReference<ScreenSizeProvider>? dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            dotNetRef = DotNetObjectReference.Create(this);
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv_c2658095691f4e19b148408a3d210ef9/Components/ScreenSizeProvider.razor.js");
            await module.InvokeVoidAsync("initialize", dotNetRef);
        }
    }

    [JSInvokable]
    public void OnViewportCategoryChanged(string category)
    {
        var newSize = category switch
        {
            "Mobile" => ScreenSize.Mobile,
            "Tablet" => ScreenSize.Tablet,
            _ => ScreenSize.Desktop
        };

        if (newSize != currentSize)
        {
            currentSize = newSize;
            StateHasChanged();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (module is not null)
        {
            await module.InvokeVoidAsync("dispose");
            await module.DisposeAsync();
        }
        dotNetRef?.Dispose();
    }
}

let dotNetHelper = null;
let resizeHandler = null;

function getCategory(width) {
    if (width < 768) return "Mobile";
    if (width < 1024) return "Tablet";
    return "Desktop";
}

export function initialize(helper) {
    dotNetHelper = helper;

    let currentCategory = getCategory(window.innerWidth);
    dotNetHelper.invokeMethodAsync("OnViewportCategoryChanged", currentCategory);

    resizeHandler = () => {
        const newCategory = getCategory(window.innerWidth);
        if (newCategory !== currentCategory) {
            currentCategory = newCategory;
            dotNetHelper.invokeMethodAsync("OnViewportCategoryChanged", newCategory);
        }
    };

    window.addEventListener("resize", resizeHandler);
}

export function dispose() {
    if (resizeHandler) {
        window.removeEventListener("resize", resizeHandler);
        resizeHandler = null;
    }
    dotNetHelper = null;
}

